starter.solution.py:
def respond(words):
    if words == ["look"]:
        return "You look around."
    return "I do not understand."

unitTests:
@test("look, quit, empty")
def _():
    check_eq(respond(["look"]), "You look around.")
    check_eq(respond(["quit"]), "Bye.")
    check_eq(respond(["exit"]), "Bye.")
    check_eq(respond([]), "Say something.")

@test("going")
def _():
    check_eq(respond(["go", "north"]), "You go north.")
    check_eq(respond(["go", "west"]), "You go west.")
    check_eq(respond(["go", "up"]), "You cannot go up.")

@test("taking")
def _():
    check_eq(respond(["take", "key"]), "Taken: key.")
    check_eq(respond(["take", "key", "lamp", "map"]), "Taken: key, lamp, map.")

@test("everything else")
def _():
    check_eq(respond(["dance"]), "I do not understand.")
    check_eq(respond(["go"]), "I do not understand.")
    check_eq(respond(["go", "north", "fast"]), "I do not understand.")

